// <auto-generated> by cs/tools/ts2cs.mjs from src/sim/farming.ts, then fixed by hand where it says so.
// Farming: a renewable food source.
//
// The player designates farm plots on floor tiles, each with a crop. A plot cycles:
//   empty --(sow job)--> growing --(its crop's grow time)--> ripe --(harvest job)--> empty, plus the yield
// Sowing and harvesting are both the `farm` job type (jobs.ts). Harvested
// food lands on the plot and is hauled to storage like any other item.
//
// Crops: potatoes (quick, one food), wheat (slow, three food), herbs (slow,
// one medicine). Outdoors they grow as the season allows (seasons.ts); in a
// complete greenhouse they grow at full speed all year, winter included.
//
// Chicken coops (furniture) lay a food every EGG_EVERY ticks, half as often in winter.
#nullable disable warnings
namespace LoonieRoo.Sim;

public static partial class Farming
{

    public static readonly JsRecord<CROPS> CROPS = new() { ["potato"] = new() { grow = 2400, yield = 1, item = "food", label = "Potatoes" }, ["wheat"] = new() { grow = 4800, yield = 3, item = "food", label = "Wheat" }, ["herb"] = new() { grow = 4800, yield = 1, item = "medicine", label = "Herbs" } };

    /// <summary>Ticks from sowing to ripe for potatoes: half a day (12 in-game hours, 2 min at 1x).</summary>
    public static readonly double GROW_TICKS = CROPS["potato"].grow;

    /// <summary>Ticks of work to sow or to harvest a plot.</summary>
    public const int FARM_WORK = 20;

    /// <summary>A coop lays a food this often (twice as long in winter).</summary>
    public const int EGG_EVERY = 1200;

    public static FarmPlot? plotAt(SimState state, int x, int y)
    {
        return state.farm.find((p) => (p.x == x) && (p.y == y));
    }
    public static FarmPlot? plotAt(SimState state, double x, double y) => plotAt(state, (int)x, (int)y);

    public static FarmPlot? getPlot(SimState state, string id)
    {
        return state.farm.find((p) => p.id == id);
    }

    public static double growTicks(FarmPlot plot)
    {
        return Js.Get(CROPS, plot.crop).grow;
    }

    public static bool isRipe(FarmPlot plot)
    {
        return plot.planted && (plot.growth >= growTicks(plot));
    }

    /// <summary>Does this plot need a survivor right now (to sow, or to harvest)?</summary>
    public static bool needsWork(FarmPlot plot)
    {
        return !plot.planted || isRipe(plot);
    }

    public static FarmPlot addPlot(SimState state, int x, int y, string crop = "potato")
    {
        FarmPlot plot = new FarmPlot { id = $"p{Js.Str(state.nextId++)}", x = Js.I(x), y = Js.I(y), crop = crop, planted = false, growth = 0 };
        state.farm.push(plot);
        return plot;
    }
    public static FarmPlot addPlot(SimState state, double x, double y, string crop = "potato") => addPlot(state, (int)x, (int)y, crop);

    public static bool isCrop(object c)
    {
        return ((Js.Eq(c, "potato")) || (Js.Eq(c, "wheat"))) || (Js.Eq(c, "herb"));
    }

    public static void removePlot(SimState state, FarmPlot plot)
    {
        var i = state.farm.indexOf(plot);
        if (i >= 0)
        {
            state.farm.splice(i, 1);
        }
    }

    /// <summary>Removes the plot on a tile (if any), e.g. when a wall or door is built there.</summary>
    public static void clearPlot(SimState state, Point p)
    {
        var plot = plotAt(state, p.x, p.y);
        if (Js.T(plot))
        {
            removePlot(state, plot);
        }
    }

    /// <summary>The harvest: the crop's yield on the plot.</summary>
    public static void harvest(SimState state, FarmPlot plot)
    {
        var crop = Js.Get(CROPS, plot.crop);
        for (var n = 0; n < crop.yield; n++)
        {
            Items.spawnItem(state, crop.item, plot.x, plot.y);
        }
        plot.planted = false;
        plot.growth = 0;
    }

    /// <summary>Crops grow every tick (as the season allows, or always in a greenhouse); plots whose tile stopped being floor are lost. Coops lay.</summary>
    public static void updateFarm(SimState state)
    {
        if (!Time.slowTick(state.tick))
        {
            return;
        }
        FurnitureMod.regrowTrees(state);
        var outdoors = Seasons.cropGrows(state);
        var greenhouses = (state.farm.length > 0) ? Rooms.completeRooms(state, "greenhouse") : new JsSet<double>();
        foreach (var plot in Js.Iter((state.farm).ToList()))
        {
            if (Grids.getTile(state.grid, plot.x, plot.y) != "floor")
            {
                removePlot(state, plot);
                continue;
            }
            var growth = greenhouses.has(Rooms.labelAt(state, plot.x, plot.y)) ? 1 : outdoors;
            if (Js.T(plot.planted) && (plot.growth < growTicks(plot)))
            {
                plot.growth = JsMath.min(growTicks(plot), plot.growth + growth);
            }
        }
        var every = (Seasons.seasonOf(state.tick) == "winter") ? (2 * EGG_EVERY) : EGG_EVERY;
        if ((state.tick > 0) && ((state.tick % every) == 0))
        {
            foreach (var f in Js.Iter(FurnitureMod.ofKind(state, "coop")))
            {
                Items.spawnItem(state, "food", f.x, f.y);
            }
        }
    }

    public static Point plotPoint(FarmPlot plot)
    {
        return new Point { x = Js.I(plot.x), y = Js.I(plot.y) };
    }
}
